function BalancingCheck(term_orders):
    finite <- [(i, o) for (i, o) in term_orders if o != +inf]
    if finite is empty: return (True, [])
    m <- min(o for (i, o) in finite)
    minimizers <- [i for (i, o) in finite if o == m]
    return (|minimizers| >= 2, minimizers)

function EnumerateSolutionOrders(terms, n_lo, n_hi):
    result <- []
    for n in [n_lo .. n_hi]:
        vals <- [ sum_i e_i*(n - i) for e in terms ]
        m <- min(vals)
        if count(vals == m) >= 2:
            result.append(n)
    return result

